INSERT INTO birds (id, latin_name, category, description_local, description_en, habitat_en, food_habits_en, migration_en, cultural_en, map_image) VALUES
  (1, 'Cathartes aura', 'Birds of Prey', NULL, 'Turkey Vultures can be up to 32″ in length with a wingspan of 72″. The adult’s head is small in proportion to its body and is red in color. Its body feathers are mostly brownish-black, but flight feathers are a silver-gray.', 'Turkey Vultures forage in a variety of habitats, including grasslands, open woodlands, and farmlands. They can nest on cliff ledges, under overhangs, or in river valleys.', 'Primarily carrion, but they also prey on small mammals.', 'They summer in Montana then migrate to the Southern United States and Central America for the winter.', NULL, 'turkey_vulture-text-map.png'),
  (2, 'Circus hudsonius', 'Birds of Prey', NULL, 'A medium sized hawk, 17–23″ in length with a wingspan of 38–48″, females being larger than males. Females are dark brown above and tan below. Males are pale-gray above and white below, with black wing tips. The facial disc gives them an owl-like appearance.', 'Can be found hunting in grasslands and open valleys not far from water. They nest in dense grass, snowberry patches, and hay fields.', 'Small mammals, although they also eat birds, amphibians, reptiles, and insects. Similar to owls, northern harriers have an acute sense of hearing and use sound to locate their prey.', NULL, NULL, 'northern_harrier_hawk-text-map.png'),
  (3, 'Accipiter striatus', 'Birds of Prey', NULL, 'A small hawk, 9–11″ in length with a wingspan of 23″. Adults are dark grayish-blue above, with a very dark crown. The tail is white-tipped with broad gray bars. Underparts are white with rust-colored barring from the throat to the legs; and white under the base of the tail. The legs are yellow and the iris of the eye is red. In flight, the Sharp-shinned Hawk exhibits a squared tail.', 'Can be found hunting in heavy conifer forests, and occasionally in open areas. It is most numerous in the foothills and lower reaches of the mountain forests.', 'Almost entirely songbirds. Occasionally small mammals and insects.', NULL, NULL, 'sharp_skinned_hawk-text-map.png'),
  (4, 'Buteo jamaicensis', 'Birds of Prey', NULL, '19–25″ in length with a wingspan of 46–58″. Upperparts are dark-brown; underparts whitish-gray with a belly band of dark speckling; and the tail is a rusty-red color. Seen from below, there are dark brown edges on the wings and dark brown shoulder patches. The dark belly band is prominent and the red tail is much paler. <i>Chilaxté</i> ‘wraps its wings’ is the stem word for a generic hawk.', 'Nests in trees and on cliffs. Hunts over grasslands, open woodlands, and agricultural areas.', 'Primarily ground squirrels and other small rodents but also rattlesnakes.', 'Winters in the Southern United States, although some winter in Montana. Migration to Southern Montana is late October through mid-March to May.', NULL, 'redtail_hawk-text-map.png'),
  (5, 'Buteo jamaicensis kriderii', 'Birds of Prey', NULL, '19–25″ in length with a wingspan of 46–58″. A subspecies of red-tail, the Krider’s Red-tailed Hawk lives year-round in Crow Country. Unlike the more common Red-tailed Hawk, <i>Buteo jamaicensis</i>, that also lives in Montana and Wyoming, the Krider''s Red-tailed Hawk has distinctly paler plumage, and a white head and breast. <i>Chilaxté</i> ‘wraps its wings’ is the stem word for a generic hawk.', 'Nests in trees and on cliffs. Hunts over grasslands, open woodlands, and agricultural areas.', 'Primarily ground squirrels and other small rodents but also rattlesnakes.', 'Winters in the Southern United States, although some winter in Montana. Migration to Southern Montana is late October through mid-March to May.', NULL, 'redtail_hawk-text-map.png'),
  (6, 'Buteo swainsoni', 'Birds of Prey', NULL, 'Adults are up to 22″ in length with a wingspan of up to 52″. Upperparts dark-brown while underparts are white with chestnut-brown bib. In flight, the wing undersides appear two-toned, with the flight feathers dark and the leading edge of the wing white. <i>Chilaxté</i> ‘wraps its wings’ is the stem word for a generic hawk.', 'Nests in river bottom forests, brushy coulees, and shelterbelts. Hunts in open land, especially along river bottoms.', 'Songbirds, small mammals, and insects.', 'Summers in South Central Montana mid-May through September. They migrate in large flocks to Argentina for the winter.', NULL, 'swainsons_hawk-text-map.png'),
  (7, 'Pandion haliaetus', 'Birds of Prey', NULL, '24″ in length with a wingspan of up to 72″. Upperparts are dark-brown, underparts white with a barred tail. The head is white with a brown stripe extending from the eye to the shoulders. Its wing’s undersides are two-toned, with white along the leading edge and brown barred flight feathers. <i>Chilaxté</i> ‘wraps its wings’ is the stem word for a generic hawk.', 'Nests in tall trees near lake, reservoirs, and rivers.', 'Primarily fish.', 'Migrates to Central and South America in the winter. Summers in South Central Montana late April through September.', NULL, 'osprey-text-map.png'),
  (8, 'Accipiter cooperii', 'Birds of Prey', NULL, '17 to 20″ in length for females, males slightly smaller. Blue-gray on the back with a black crown and paler neck and face. The belly is white with horizontal reddish-brown barring. The iris of the eye is deep-red and the feet are yellow. <i>Chilaxté</i> ‘wraps its wings’ is the stem word for a generic hawk (<i>Buteo sp.</i>).', 'Nests in dense deciduous or coniferous forests. Hunts in forests or over open country.', 'Primarily small to medium sized birds, but also snakes and small rodents. The Cooper’s hawk is known for its stealth and agility in hunting birds and even bats.', 'Winters in the southern United States, although some winter in Montana. Migration to Southern Montana is from early September to late April.', NULL, 'coopers_hawk-text-map.png'),
  (9, 'Buteo lagopus', 'Birds of Prey', NULL, 'Rough-legged Hawks can be up to 24″ in length with a wingspan 56″. Adults have a dark-brown back and wings; a light mottled-brown head; a wide, dark brown belly band, a long white tail with black terminal bands; feathered legs; and relatively small talons.', 'Hunts over grasslands and agricultural land.', 'Small mammals such as ground squirrels, rabbits, and mice.', 'Nests in Northern Canada and Alaska and spends winters in Montana. Usually from October through March.', NULL, 'roughlegged_hawk-text-map.png'),
  (10, 'Falco mexicanus', 'Birds of Prey', NULL, 'Upperparts are a warm gray-brown with a paler dark-brown mottling below. The head has a dark-brown “moustache” mark and a white line over the eye. Dark-brown “wing pits” are visible on the undersides of the wings near the body. No difference between sexes, except that the female is a bit larger, 17″ in length with a 14″ wingspan.', 'Nests in cliffs. Hunts in grassland and prairie habitats.', 'Birds and small mammals (horned larks, meadow larks, and ground squirrels).', NULL, NULL, 'prairie_falcon-text-map.png'),
  (11, 'Falco sparverius', 'Birds of Prey', NULL, 'The smallest hawk in North America, 9 to 12″ in length with a wingspan of 20 to 24″. Males have slate-blue wings and crowns; back is reddish-brown with dark-brown horizontal barring; and the breast is light tan with light vertical streaking. The female is reddish-brown on the back and wings with dark-brown horizontal banding; and the breast is tan with heavy rufous streaking. Both sexes have a dark vertical stripe surrounding the eye. The Crow name <i>issaxchisée</i> literally translates as “big falcon,” but in this case <i>“isée”</i> means “powerful.”', 'Hunts in open habitat and nests in trees, banks, cliffs, and buildings.', 'Insects, birds, rodents, and snakes.', 'A year-round in western Montana, summers in eastern Montana from April through October.', NULL, 'kestral-text-map.png'),
  (12, 'Aquila chrysaetos', 'Birds of Prey Eagles', NULL, 'A very large raptor 33 to 38″ in length with a wingspan of 6½ to 7½′. The plumage of a mature Golden Eagle is dark-brown with golden-brown feathers on the crown, nape, and neck. The wing feathers show streaks of black and have dark tips that form a dark band along the wing’s trailing edge. The tail has a dark terminal band preceded by a gray-brown and lighter marbling. The legs are heavily feathered down to the tops of the toes.', 'Golden Eagles nest on cliffs and in large trees and hunt over prairie and open woodlands.', 'Primarily jackrabbits, ground squirrels, and carrion. They occasionally prey on deer, waterfowl, grouse, weasels, and skunks.', NULL, 'Mature Golden Eagles are considered wise from age and experience.', 'golden_eagle-text-map.png'),
  (13, 'Aquila chrysaetos', 'Birds of Prey Eagles', NULL, 'At hatching, golden eaglets show a thin, white, fluffy down coat with bare batches of skin showing through. A thicker white down will begin to form after the first week. By two months the juvenile eaglet’s plumage is complete and they are ready to leave the nest.', 'Golden Eagles nest on cliffs and in large trees and hunt over prairie and open woodlands.', 'Primarily jackrabbits, ground squirrels, and carrion. They occasionally prey on deer, waterfowl, grouse, weasels, and skunks.', NULL, NULL, 'golden_eagle-text-map.png'),
  (14, 'Aquila chrysaetos', 'Birds of Prey Eagles', NULL, 'The plumage of a juvenile eagle is dark-brown with a bi-colored tail and white wing patches. The tail feathers have a black tail band and white base. The bi-color tail is noticeable in flight and when the bird is perching. The white wing patches vary in size and are noticeable where the primary and secondary wing feathers meet.', 'Golden Eagles nest on cliffs and in large trees and hunt over prairie and open woodlands.', 'Primarily jackrabbits, ground squirrels, and carrion. They occasionally prey on deer, waterfowl, grouse, weasels, and skunks.', NULL, 'One year-old goldens are agile and vibrant like young men.', 'golden_eagle-text-map.png'),
  (15, 'Aquila chrysaetos', 'Birds of Prey Eagles', NULL, 'The 2nd and 3rd years are marked by a reduction in the white area at the tail’s base. New feathers with gray and black streaks broaden the black tail band and the the amount of white is reduced. By the end of the 3rd year a molting replaces most of the juvenile feathers. The crown and neck are replaced with more ornate, golden feathers. New flight feathers appear, that are shorter than the juvenile feathers. The word <i>déaxe</i> can be used to describe eagles in general.', 'Golden Eagles nest on cliffs and in large trees and hunt over prairie and open woodlands.', 'Primarily jackrabbits, ground squirrels, and carrion. They occasionally prey on deer, waterfowl, grouse, weasels, and skunks.', NULL, NULL, 'golden_eagle-text-map.png'),
  (16, 'Haliaeetus leucocephalus', 'Birds of Prey Eagles', NULL, 'The adult is distinguished by its white head and tail; and its yellow bill, legs, and feet. Unlike the Golden Eagle, it has no feathers on its legs. With a length of 37″ and a wingspan of 96″, it is the second largest raptor in North America next to the California Condor. There is little visual difference between males and females, with females being about 25% larger.', 'Forested areas near large lakes and rivers. The species has had major losses in numbers over the 20th century due to habitat loss.', 'Primarily fish (salmon, suckers, whitefish), but also some waterfowl.', NULL, NULL, 'bald_eagle-text-map.png'),
  (17, 'Haliaeetus leucocephalus', 'Birds of Prey Eagles', NULL, 'The plumage of the juvenile Bald Eagle is much less distinct that the adult, being dark-brown overall. The head, body, wings, and tail are dark-brown with limited mottling on the underside of the wings and on the belly. The legs and feet of the young bird are yellow like those of adults. Unlike adults, the bill is dark-gray instead of yellow.', 'Forested areas near large lakes and rivers. The species has had major losses in numbers over the 20th century due to habitat loss.', 'Primarily fish (salmon, suckers, whitefish), but also some waterfowl.', NULL, NULL, 'bald_eagle-text-map.png'),
  (18, 'Haliaeetus leucocephalus', 'Birds of Prey Eagles', NULL, 'The Bald Eagle enters its immature stage when it loses its dark brown natal or juvenile plumage. They then go through a period of lighter plumage consisting of white and brown mottling. The amount and tone of mottling changes with individual birds. The bill starts to acquire its adult yellow coloring during this period. The immature eagle begins to show the adult patterning of the white head and tail at 3.5 years.', 'Forested areas near large lakes and rivers. The species has had major losses in numbers over the 20th century due to habitat loss.', 'Primarily fish (salmon, suckers, whitefish), but also some waterfowl.', NULL, NULL, 'bald_eagle-text-map.png'),
  (19, 'Megascops kennicottii', 'Birds of Prey Owls', NULL, 'A small owl 8–10″ in length. They have a round head with ear tufts and yellow eyes. The facial disk is gray and surrounded by a black border. Wings are streaked with brown. The Western Screech Owl is similar in size to the Eastern Screech Owl, although slightly larger. Their bill is black to gray-black as opposed to the yellowish-green bill of the Eastern and their calls differ. The calls of the Western Screech Owl are a series of short whistles made at an increasing tempo or a short then long trill falling slightly at end. They also produce the high-pitched screech for which they are named.', 'Can be found in cottonwood bottomlands and along the fringes of coniferous forests.', 'Small mammals and birds.', NULL, 'Screech owls are harbingers of death and generally seen as bad omens.', 'screech_owl-text-map.png'),
  (20, 'Megascops asio', 'Birds of Prey Owls', NULL, 'A small owl 8–10″ in length. They have a round head with ear tufts, yellow eyes, and a yellowish-green or gray bill. The facial disk is white and surrounded by a black fringe. Breast is pale gray to white with brown vertical streaks. The Eastern Screech Owl is similar in size to the Western, although slightly smaller. Their bill is yellowish-green as opposed to the gray-black bill of the Western and their calls differ. The two-part call of the eastern begins as an ascending whistle, “wheee,” then a vibrating low whistle “quohohoho.”', 'Can be found in cottonwood bottomlands and along the fringes of coniferous forests.', 'Small mammals and birds.', NULL, 'Screech Owls are harbingers of death and generally seen as bad omens.', 'eastern_screech_owl-text-map.png'),
  (21, 'Athene cunicularia', 'Birds of Prey Owls', NULL, 'A very small owl, 9.5″ in length with a wingspan of 21″; long legs; a tuft-less brown head; flattened facial disc; bright-yellow eyes; prominent white eyebrows; and a white “chin” patch. Its wings are brown with white spotting; and its chest is white with variable brown barring.', 'Found in abandoned burrows of prairie dogs, ground squirrels, and badgers across South, Central, and Eastern Montana.', 'Primarily invertebrates but also small mammals, amphibians, reptiles, and birds.', 'Summers in Montana, from April to September.', 'Burrowing Owls are small but brave. They are distinct as a bird since they live underground, on the earth, and fly in the sky.', 'burrowing_owl-text-map.png'),
  (22, 'Bubo scandiacus', 'Birds of Prey Owls', NULL, 'One of the largest owls in the world, the female is 28″ in length with a wingspan averaging over 60″. It is round-headed, with no facial disc; yellow eyes; a small black beak; and heavily feathered feet. Males are almost totally white with the exception of 3 tail bands, while females have distinctive brown barring, and from 4–6 tail bands.', 'Open plains, and in coastal and agricultural areas.', 'Voles and lemmings, but also waterfowl and small mammals.', 'Breeds in the summer in the Arctic areas of Alaska and Northern Canada. Winters in Montana from mid-December through mid-February.', 'The snowy owl gave the <i>Apsáalooke</i> people the <i>ashtáahile</i> (tipi). That is why <i>Apsáalooke</i> tipis are almost exclusively white.', 'snowy_owl-text-map.png'),
  (23, 'Bubo virginianus subarcticus', 'Birds of Prey Owls', NULL, 'It is the largest subspecies of the <i>Bubo virginianus</i> (Great Horned Owl) and the majority species found in Crow Country. Up to 25″ in length with a wingspan of 60″; yellow eyes; and a gray facial disc. It significantly paler in coloration than other species of <i>Bubo virginianus</i> and has darker, but sparser barring. Due to its curiosity and lack of fear of humans, it can often be seen hunting during the day in contrast to the other, more common <i>Bubo virginianus</i>.', 'Well wooded creek bottoms amidst cottonwood and willow cover.', 'Ground squirrels, rats, mice, and rabbits.', NULL, 'Seen as a protector of <i>ashtáahile</i> (the tipi) and warned occupants of danger. This concept is applied to the house today.', 'montana_great_horned_owl-text-map.png'),
  (24, 'Bubo virginianus lagophonus', 'Birds of Prey Owls', NULL, 'More predominate in Northwest Montana and is the minority species of <i>Bubo virginianus</i> in Crow Country. Upper parts and wings are generally a darker mottled brown with a dark-brown horizontal barring from the chest to the lower abdomen. It has proportionally very large eyes that are adapted for nocturnal hunting and its wing structure allows it to have a “silent flight” and can glide at very low speeds for its size (as low as 2 mph).', 'Mixed coniferous and deciduous trees that border prairies and grasslands.', 'Small to medium sized mammals and birds.', NULL, 'Seen as a protector of <i>ashtáahile</i> (the tipi) and warned occupants of danger. This concept is applied to the house today.', 'northwestern_great_horned_owl-text-map.png'),
  (25, 'Tyto furcata', 'Birds of Prey Owls', NULL, 'Up to 16″ in length with a wingspan of 42″. The heart shaped facial disc, black eyes, and a beak resembling a nose, gives it a distinct appearance. In flight it can be distinguished from other owls by its long wings, dangling long legs, and short square tail. The head, back, and wings are a pale buff color, with fine black and white markings. The breast is white as are the sparsely feathered legs. The word <i>póopahte</i> can be used to describe owls in general.', 'Open grassland, marsh, pasture lands, croplands, and hayfields.', 'Voles are the primary food source, but also other small mammals, lizards, amphibians, and insects.', NULL, NULL, 'great_horned_owl-text-map.png'),
  (26, 'Corvus brachyrhynchos', 'Corvids, Jays', NULL, 'One of the most widespread of all North American birds, 16–20″ in length, half of that being tail, with a wingspan of 38″. Plumage is all black with iridescent feathers.', 'Found in a wide variety of habitats, particularly in open landscapes with scattered trees and small woodlots. Uses both natural habitats and those created by humans (logged areas, agricultural fields, cities, and villages). It generally avoids large areas of forest.', 'Omnivorous. Wide variety of invertebrates; amphibians; reptiles; mammals; small birds and birds’ eggs, nestlings, and fledglings; grain crops; seeds and fruits; carrion; and discarded human food.', NULL, NULL, 'crow-text-map.png'),
  (27, 'Perisoreus canadensis', 'Corvids, Jays', NULL, 'A long-tailed, small-billed jay without a crest; slightly smaller than a blue jay, 10–12″ in length. The Canada Jay has pale-gray underparts; darker gray upperparts; and a gray-white head with a darker gray nape.', 'The coniferous forests of the Rocky Mountains in the United States and Canada.', 'Arthropods, berries, carrion, nestling birds, and fungi. They use their saliva to fasten food to trees so it may be obtained throughout the winter.', NULL, NULL, 'camp_robber-text-map.png'),
  (28, 'Nucifraga columbiana', 'Corvids, Jays', NULL, 'A jay-size corvid, over 11″ in length with a wingspan of 24″. Its plumage is similar to that of the Northern Mockingbird, but it is larger with a longer, straighter bill. Has a sharp grating “craaaww” call that is audible at a great distance.', 'Conifer forests at higher elevations and Ponderosa pine, limber pine, and Douglas firs at lower elevations.', 'Fresh and stored pine seeds (mostly Ponderosa pine), but also insects and spiders, small animals, and carrion.', NULL, NULL, 'clarks_nutcracker-text-map.png'),
  (29, 'Pica hudsonia', 'Corvids, Jays', NULL, 'Medium sized bird 18–24″ from tip to tail, with close to half of that length being tail. Black head, breast, shoulders and back; with contrasting white scapulars; white belly; large, white markings on its primary wings; and iridescent, bluish-green wings and tail. The tail is made up of long, layered feathers; the middle pair extending further than the rest. Little difference between sexes.', 'Found forging in open meadows, grasslands, or sagebrush. Frequents human habitats such as livestock feedlots and barnyards. Historically followed Native Americans and lived off the remains of their hunts.', 'Ground-dwelling arthropods, seeds, and carrion. Historically associated with bison herds, it now lands on the backs of cattle to glean ticks and insects from them.', NULL, 'Magpies watch their areas and report news to humans.', 'magpie-text-map.png'),
  (30, 'Corvus corax', 'Corvids, Jays', NULL, 'A very large corvid, adults up to 25″ in length and over 3 lbs. Plumage is an entirely glossy-black with relatively long, pointed wings. Ravens differ from crows by being larger overall; and with a larger and heavier black beak; shaggy feathers around the throat; and a longer, wedge-shaped tail.', 'One of the most widely spread, naturally occurring birds in North America. Found in a wide variety of boreal, conifer, and deciduous forests; prairies and grasslands; towns, and agricultural areas.', 'Arthropods, amphibians, reptiles, birds, small mammals, carrion, grains, and berries.', NULL, NULL, 'raven-text-map.png'),
  (31, 'Tympanuchus phasianellus', 'Gamebirds', NULL, 'Plumage is mottled dark and light browns against a white background; breasts are lighter with brown V-shaped markings. Adult males have a yellow comb over their eyes, and a violet patch displayed on their neck. Females are similar with a less pronounced comb.', 'Abundant across Central and Eastern Montana. Found in grasslands interspersed with shrub and sagebrush-filled coulees. Sharp-tailed grouse were once found west of the Continental Divide, but there have been no reportings from that region in recent years.', 'Seeds, grasses, fruit, and insects.', NULL, 'Sharptailed and sage grouse taught <i>Apsáalooke</i> people how to dance.', 'sharptailed_grouse-text-map.png'),
  (32, 'Phasianus colchicus', 'Gamebirds', NULL, 'A large, popular game bird, up to 36 inches in length and weighing 3 pounds. The adult male has a long, barred tail; copper-red plumage with iridescent markings; white collar; dark green neck; and a bright red face patch. The adult female has a similar tail; but a dull, mottled-brown back and tan breast.', 'Pheasants were introduced into North America in 1773 and have since become well established in the Rocky Mountain states. Found in open grassland and cropland areas with brushy cover, especially near rivers or lakes.', 'Grains (wheat and barley), berries, and invertebrates.', NULL, NULL, 'pheasant-text-map.png'),
  (33, 'Bonasa umbellus', 'Gamebirds', NULL, 'A medium-sized bird 16–20″ in length with a wingspan of 20–25″. The head, neck, and back are gray-brown; with light barring against white on its breast. The tail is the same brownish-gray, with regular barring and a broad black band near the end. There are two separate colors of birds, brown and gray. The brown have a more uniform coloring in their plumage. Both sexes are of similar size and markings.', 'Found in dense, brushy, mixed-conifer and deciduous tree cover, often along stream bottoms.', 'In winter they eat deciduous tree buds and shrubs. In summer, they subsist on a mixed diet of insects, green plants, and berries', NULL, NULL, 'spruce_grouse-text-map.png'),
  (34, 'Dendragapus obscurus', 'Gamebirds', NULL, 'Adult males range from 18.5–22.5″, while adult females are slightly smaller. Males have slate-colored upperparts; white-based neck feathers around reddish-purple air sacs; and yellowish-orange eye combs. Females tend to be browner than males and have barring on the head, neck, and back. Both sexes have uniform blue-gray breasts and bellies, and a dark tail with gray band.', 'Conifer forests of higher elevations in the winter and grassy areas and deciduous  thickets in the summer.', 'Conifer needles in the winter. Insects, green plants, and berries in the summer.', NULL, NULL, 'blue_grouse-text-map.png'),
  (35, 'Centrocercus urophasianus', 'Gamebirds', NULL, 'The largest grouse in North America, 25–30″ in length, with pointed tail feathers; feathered legs; and mottled gray-brown, tan, and black plumage. Males have a blackish-brown throat patch and a bright-yellow eye comb. In courtship, the male puffs out its white chest, inflates its two yellow air sacs, and raises and spreads its tail. While the head is thrown back on its shoulders, the air sacs deflate with a loud popping sound.', 'Closely associated with sagebrush and found on open plains, high valleys, and mountainsides.', 'Mostly sage leaves and buds, also insects.', NULL, 'Sharptailed and sage grouse taught <i>Apsáalooke</i> people how to dance.', 'sage_grouse-text-map.png'),
  (36, 'Meleagris gallopavo', 'Gamebirds', NULL, 'Adult male can weigh up to 24 lb. and be 49″ in length. The male is much larger than the female, and has areas of red, purple, green, copper, bronze, and gold iridescence; whereas females have a duller, gray plumage. The male has a reddish head and throat, with wattles on the throat and neck. During mating season, they strut by puffing out their feathers and spreading their tails.', 'Open Ponderosa pine forests and grasslands; grain fields and livestock feeding areas in the late fall and winter.', 'Insects (mainly grasshoppers), berries; including bearberry, snowberry, skunkbrush, and sumac.', NULL, 'Called ‘enemy’s bird’ from the fact that the <i>Apsáalooke’s</i> enemies, the Cheyenne, used turkey feathers to fletch their arrows. This is also reflected in the <i>Apsáalooke</i> name for Cheyenne, <i>Isaashpuushé</i> (Striped Feather Arrows).', 'turkey-text-map.png'),
  (37, 'Aeronautes saxatalis', 'Hummingbirds, Swifts', NULL, 'The White-throated Swift is 7″ in length with a wingspan of 13″. Its back and wings are blackish-brown or black, and its breast, belly, chin, and throat are white. They usually remain airborne all day, flying and foraging, until they roost in the late afternoon or evening.', 'Roosts in cliffs, bluffs, and canyons, as well as man-made structures like bridges and overpasses.', 'Entirely flying insects (beetles, flies, bees).', 'Summers in Montana from early May through mid-September.', NULL, 'whitethroated_swift-text-map.png'),
  (38, 'Chaetura pelagica', 'Hummingbirds, Swifts', NULL, '6″ in length with a 12″ wingspan. Upperparts are glossy, dark, olive-brown. Underparts are grayish-brown; throat, chin, and cheeks are pale-colored; and the tail is very short and rounded. Wings are curved and long, extending far beyond the tail when folded. The Chimney Swift can only perch on vertical surfaces. It is typical behavior for them to fly all day and only come down at night to roost.', 'It nests on vertical surfaces, almost always human-built structures, typically chimneys.', 'Entirely flying insects (beetles, flies, bees).', 'A long-distance migrant that winters in South America and summers in the Eastern half of the United States. Occasional spottings in Montana.', NULL, 'chimney_swift-text-map.png'),
  (39, 'Chordeiles minor', 'Hummingbirds, Swifts', NULL, 'A small, nocturnal bird 9″ long with a wingspan of 24″, a flat head, and large eyes. It has a small bill, but a deceptively large mouth. Long, slender wings extend beyond its notched tail; the primary wings have pronounced, white patches; and intricate brown and white patterning is visible on its upper and lower parts.', 'Coastal sand dunes and beaches, woodland clearings, prairies, and plains', 'Solely flying insects.', 'Summers in Montana from June through September.', NULL, 'nighthawk-text-map.png'),
  (40, 'Selasphorus rufus', 'Hummingbirds, Swifts', NULL, 'A small hummingbird 3″ in length with a long slender bill. Adult males are reddish-brown above with a bright, iridescent, red throat. Females have green backs; white throats and breasts; and can vary from having brownish-green streaking to multiple scarlet spots. Both males and females can be aggressively territorial.', 'Forest edges, streamsides, and mountain meadows of the Northern Pacific coast and Rocky Mountains.', 'Primarily flower nectar (tubular flowers such as columbines, paintbrush, and scarlet sage), but occasionally insects.', 'Can be found in Montana mid-February through mid-December.', NULL, 'rufous_hummingbird-text-map.png'),
  (41, 'Zenaida macroura', 'Pigeons, Doves', NULL, 'A mid-sized bird approximately 12″ in length with a small head and long, pointed tail. Grayish-blue or grayish-brown upperparts with yellow-brown underparts. Crescent shaped black mark below the eyes. Wings and tail feathers are gray; tail feathers have black-bordered white tips. Eyes are dark-brown and bordered by bluish-skin. Adult male slightly more colorful than female. Males have a bluish-crown and nape, while the females are brownish. Species is known for its plaintive cooing.', 'Found in urban areas, farms, prairies, grasslands, and lightly wooded areas. Tends to avoid thick forests.', 'Exclusively seeds. Rapeseed, corn, millet, safflower, and sunflower seeds.', NULL, NULL, 'mourning_dove-text-map.png'),
  (42, 'Columba livia domestica', 'Pigeons, Doves', NULL, 'Mid-size bird 12–14″ in length with a slate-gray head and body; green-purple iridescent neck; ash-gray wings; and a tail with dark, often black, barring. There can be major variations in plumage due to centuries of selective breeding. The pigeon is the world’s oldest domesticated bird, dating back more than 5000 years.', 'Found in open and semi-open environments, urban areas and farms where they can forage on the ground.', 'Exclusively seeds. In towns and cities the primary food is refuse, especially bread and bread products, such as pastries and pizza crusts.', NULL, NULL, 'pigeon-text-map.png'),
  (43, 'Mycteria americana', 'Shorebirds', NULL, 'Wood Storks are large wading birds and the only stork species that lives in North America. They can be 33–45″ in height with a wingspan of 55–71″. The downward-curved bill is very long; its plumage is mostly white; and the tail and wing tips are black with hints of green and purple.', 'Wood Storks are found in the coastal areas of the United States ranging from South Carolina to Florida, but have been observed as vagrants across the United States. There have been two documented sightings along the Madison River in Southwestern Montana in the past century. Habitat alteration has been the main threat to Wood Stork populations in the North America.', 'Mainly fish, but also crabs, insects, and frogs.', NULL, 'The <i>Apsáalooke</i> name for stork derives from the Euro-American folklore that storks bring babies.', NULL),
  (44, 'Megaceryle alcyon', 'Shorebirds', NULL, 'The Belted Kingfisher is 11–13″ in height with a stocky body and a large head topped with a ragged double-pointed crest. Males have a blue-gray band across their underparts. Females also have a blue-gray band and an additional reddish-brown band across the lower breast.', 'Streams, rivers, ponds, and lakes. Nests in earthen banks where burrows can be dug.', 'Mainly fish. Also mollusks, crustaceans, insects, amphibians, reptiles, young birds, small mammals, and berries.', 'Summers in Eastern Montana late March to late October. A year-round resident in Western Montana.', NULL, 'kingfisher-text-map.png'),
  (45, 'Cinclus mexicanus', 'Shorebirds', NULL, 'A stocky, gray bird 6.5″ long with a wingspan of 9″. White feathers on the eyelids cause the eyes to flash white as it blinks. Females similar in appearance, but smaller in size.', 'Prefers streams with sand, pebble, or rocky bottoms, which provide aquatic invertebrates for food. Shorelines with large boulders or fallen trees that provide shelter from predators.', 'Aquatic invertebrates, insects, and insect larvae. Occasionally small fish.', NULL, NULL, 'dipper-text-map.png'),
  (46, 'Gallinago delicata', 'Shorebirds', NULL, 'A medium-sized shorebird about 11″ in length, with a long, straight bill. Upperparts a mixture of brown, black, and gray spots and streaks. Tail is a reddish-brown. Brown streaks and spots cover the neck and breast; underparts and belly are white.', 'In the summer they are found in moist meadows. In the winter along warm, bog-bordered valley streams.', 'Larval insects, crustaceans, earthworms, and mollusks.', NULL, NULL, 'snipe-text-map.png'),
  (47, 'Numenius americanus', 'Shorebirds', NULL, 'The largest shorebird in North America, 26″ in length with a 35″ wingspan and a disproportionate, downward-curving bill that can measure as much as 9″ in length. Light-brown with dark-brown streaks on the crown and back.', 'Breeds in prairies and moist meadows. Avoids areas with trees, dense shrubs, or tall, dense grasses.', 'It uses its long beak to probe in mudflats for invertebrates and also small vertebrates during the breeding season of summer. During winters it feeds in tidal areas primarily on crabs, shrimp, and bivalves.', 'Summers in Montana mid-March through September.', NULL, 'curlew-text-map.png'),
  (48, 'Charadrius vociferus', 'Shorebirds', NULL, '8–11″ in length with a wingspan of 23–25″. Upperparts are grayish-brown and underparts white with 2″ wide black bands across the breast. Its name is an onomatopoeia of its call, “kil-deer” or “kee-deeyu.” Very little difference between males and females.', 'Open areas, mudflats, pastures, athletic fields, airports, golf courses, or parking lots.', 'Invertebrates, especially earthworms, grasshoppers, beetles, and snails.', 'Summers in Central and Eastern Montana early to mid-April through September.', NULL, 'killdeer-text-map.png'),
  (49, 'Anarhynchus montanus', 'Shorebirds', NULL, 'Medium-sized ground bird 5–9″ in height and 8–10″ in length. Upperparts are sandy-brown; underparts and face are whitish; bill is black; and eyes are auburn-colored. During breeding there is a black stripe from the bill to the eye and the forecrown is darkly mottled. A much quieter bird than its relative the Killdeer.', 'Prefers dry habitat with short grass and bare ground, especially in prairie dog colonies.', 'Forages from the ground, primarily on insects (grasshoppers, crickets, beetles, flies, ants).', 'Summers in Central and Eastern Montana early to mid-April through September.', NULL, 'mountain_plover.png'),
  (50, 'Larus californicus', 'Shorebirds', NULL, 'A medium gull 18–24″ in length with a wingspan of up to 48–54″. Body is mainly white with a gray back and wings. Its bill is yellow with a black ring and red spots. Legs are yellow, and eyes are brown. The yellow-green legs and black and red spots on the lower mandible distinguish this species from all other gulls.', 'Prefers larger lakes, but also ponds and rivers, especially in spring and fall.', 'Insects, crustaceans, and amphibians.', 'From March to May and then again from August to November.', NULL, 'california_gull.png'),
  (51, 'Leucophaeus pipixcan', 'Shorebirds', NULL, 'A small inland gull averaging 14.5″ in length with a wingspan of 36″. Body is white and its back and wings are much darker gray than all other gulls. The wings have black tips with an adjacent white band. The bill and legs are dark red. The distinctive black hood of breeding season mostly disappears and the red bill becomes black in the winter months.', 'Prefers large, prairie marsh complexes.', 'Insects, earthworms, and arachnids.', 'Can be found in Montana from mid-April through mid-October.', NULL, 'franklin_gull.png'),
  (52, 'Plectrophenax nivalis', 'Songbirds', NULL, 'A medium sized bird 15″ in length with a wingspan of 15″. Male is white with the exception of its black back, central tail feathers, and black and white wings. Females have reddish-brown streaks on their backs and a band across their breasts.', 'Open grasslands; roadsides and farmyards after a heavy snowfall; debris piled up by wind on shores of lakes and rivers.', 'Forages for weed and grass seeds.', 'Winters in Montana from mid-March to April.', '<i>Ischíkiia</i> and <i>ischíkiikaate</i> is how <i>Apsáalooke</i> people hear the song of the Snow Bunting.', 'snow_bunting-text-map.png'),
  (53, 'Sturnella neglecta', 'Songbirds', NULL, 'Adults have bright-yellow underparts with a black “V” on the breast. Their upper parts are a pattern of buffs and browns, with black streaks and bars. The bill is long and pointed and the head striped with light-brown and black bands. Wings and tail feathers are barred with black and brown. Little difference between male and female.', 'Native grasslands and pastures, hay and alfalfa fields, roadside vegetation, and orchards.', 'Grain and weed seeds, insects (beetles, weevils, wireworms, cutworms, grasshoppers, and crickets).', 'Summers in Montana from mid-Spring through late October.', 'Meadowlarks are gossips. They speak about what people have done wrong.', 'meadowlark-text-map.png'),
  (54, 'Eremophila alpestris', 'Songbirds', NULL, 'A small, ground-dwelling songbird, 6–8″ in length, with “horns” which can be raised or lowered but are usually erect in males. Upperparts are shades of brown streaked with black. Underparts cinnamon to white. Face has a striking yellow and black pattern.', 'Open and barren fields. Avoids forests.', 'Mostly seeds in the winter, but insects and seeds during the breeding season.', NULL, NULL, 'horned_lark-text-map.png'),
  (55, 'Sturnus vulgaris', 'Songbirds', NULL, 'A medium sized bird, 7.5–9″ in length with glossy black plumage showing specks of purple and green iridescence, and a long, yellow bill. No visual difference between males and females. Starlings can form huge, tight, shape-changing formations, called <i>murmurations</i>, that frequently expand and contract without any leader.', 'The starling was introduced from Europe to North America in the late 19th century. Since, they’ve become one of the most common bird species with a population of 150 million and occupying an area from southern Canada and Alaska to Central America. Adaptable to human environments, they forage in mown or grazed fields in urban as well as agricultural areas.', 'Invertebrates, fruits, berries, grains, and seeds.', NULL, 'The murmurations (clouds) created by starlings are seen as a sign of fall and the oncoming winter.', 'starling-text-map.png'),
  (56, 'Troglodytes aedon', 'Songbirds', NULL, 'A small bird known and beloved for its song. Pugnacious for their size (6″ in length with a wingspan of 6.5″), its upperparts range from dull, grayish-brown to reddish-brown; and the underparts are pale-gray to pure white. Blackish barring to the wings, tail, and flanks. The bill is long and thin, with a blackish upper mandible and a yellow lower mandible.', 'Deciduous or mixed deciduous-coniferous woodlands of the mountains, shrubby woodlands and suburban backyards and city parks of Eastern Montana.', 'Insects such as butterfly larvae, and beetles, also spiders and snails.', 'Summers in Montana, mid-May to early September.', NULL, 'wren-text-map.png'),
  (57, 'Poecile atricapillus', 'Songbirds', NULL, 'Very small, up to 5.5″ in length. Solid black cap and bib, and white cheeks. Breast and underparts are grayish-white. Back is an un-streaked greenish-gray, wings and tail are dark-gray. Sexes are similar in appearance, with males slightly longer than females in wing and tail.', 'Deciduous and mixed deciduous/coniferous woodland, open woods and parks, and cottonwood groves.', 'The Black-capped Chickadee feeds primarily on insects (especially caterpillars) in the summer and seeds in the winter, and is known for its ability to cache food for later use. Their survival rates in extremely cold climates like Montana benefit from this access to cached food.', NULL, 'Chickadees are knowledgeable and are able to identify the season by their changing song throughout the year (due to changes in their tongues).', 'chickadee-text-map.png'),
  (58, 'Icterus galbula', 'Songbirds', NULL, 'A medium sized bird, 8.5″ in length with a wingspan of 12″. Males are a vivid, bright-orange on their underparts with a black head and shoulders, and dark-gray and white wings. Females have yellowish-brown upperparts and dull-orange underparts.', 'More common in the Northeastern United States. Found in open woodlands and partially wooded wetlands also orchards, farmland, urban parks and suburban areas', 'Nectar, small fruits, caterpillars, and spiders.', NULL, NULL, 'oriole-text-map.png'),
  (59, 'Icterus bullockii', 'Songbirds', NULL, 'A medium sized bird, 7.5″ in length with a wingspan of 12″.  Adult males have strongly contrasting orange and black plumage; a black throat patch; and a white wing bar. The underparts, breast, and face are orange; and the back, wings, and tail are black. A black line extends from each eye to the black crown. Adult females have gray-brown upperparts; a duller yellow on the breast; and an olive crown.', 'Native to Western North America. Prefers open woodland areas, especially riparian (river) woodlands with large cottonwoods, sycamores, and willows.', 'Eats mostly insects, especially butterfly and moth larvae and pupae, grasshoppers, crickets, and beetles.', NULL, NULL, 'bullocks_oriole-text-map.png'),
  (60, 'Spinus tristis', 'Songbirds', NULL, 'A small bird, up to 5.5″ in length with a wingspan of 8.5″. Adult males have a lemon-yellow body with a rich-black forehead and crown. Wings are black with white tips, and the tail is black with white innerwebs. Females have upperparts of olive-brown and olive-yellow underparts with wing coloring; similar to the male. The male’s coloring changes from bright-yellow to olive-brown in the winter.', 'Open fields and meadows as well as roadsides, orchards, and gardens.', 'Almost exclusively seeds, including thistle, dandelion, ragweed, mullein, cosmos, and sunflower.', 'Year-round in Western Montana, summers in Eastern Montana late May through September.', NULL, 'goldfinch-text-map.png'),
  (61, 'Tyrannus tyrannus', 'Songbirds', NULL, 'A medium sized bird, 9″ in length with a wingspan of 15″. It has contrasting black upperparts, white underparts, and pointed wings. Upper chest is marked by a faint, grayish band. The dark-black head is slightly crested, especially in males. Both males and females aggressively defend their nests, even against much larger birds such as ravens and crows.', 'Commonly found in open areas with scattered trees and bushes, where they perch while foraging for insects.', 'Entirely insects.', 'Summers in Montana, from mid-May through mid-September.', NULL, 'kingbird-text-map.png'),
  (62, 'Dolichonyx oryzivorus', 'Songbirds', NULL, 'Adults are 7″ long with short finch-like bills. Males are mostly black with creamy-yellow napes and white scapular feathers, lower backs, and rumps. Females are pale-yellow with brown streaks on the back, rump, sides, and heads. Known for its joyous, gurgling phrasing in its song, with each note being a different pitch.', 'Hayfields, marshes, and meadows. Migrating Bobolinks are known for grazing in rice fields and have been nicknamed ‘rice bird.’', 'Weed seeds, larvae, and insects.', 'Summers in Montana, mid-May through August.', NULL, 'bobolink-text-map.png'),
  (63, 'Calamospiza melanocorys', 'Songbirds', NULL, 'A small songbird 7″ in length. Breeding males are distinctive with their all-black body and the white patch on their wings. Females and non-breeding males are grayish-brown with white stripes. Breeding is in dispersed colonies where males deliver various songs to declare their nesting territory.', 'Short-grass and mixed-grass fields, roadsides, and hayfields.', 'Forages on the ground; seeds in the winter and insects in the summer.', 'Summers in Montana from early May through late August.', NULL, 'lark_bunting-text-map.png'),
  (64, 'Euphagus cyanocephalus', 'Songbirds, Blackbirds', NULL, 'Medium size black bird 8–10″ in length. The adult male has a glossy violet head and neck. The female is grayish-brown with a light-violet gloss on head and neck, and a light-metallic green sheen on rest of the body.', 'Comfortable among humans in open, urban areas such as residential lawns, golf courses, cemeteries, and parks.', 'Forages in flocks, mainly on seeds, insects, and some berries.', NULL, NULL, 'brewers_blackbird-text-map.png'),
  (65, 'Molothrus ater', 'Songbirds, Blackbirds', NULL, 'Medium size, 6–9″ in length with a wingspan of 14″. The adult male has a plain brown head, neck, and upper chest. The rest of the body is a glossy, greenish-black. The adult female is a duller gray with fine streaking on its underparts.', 'Woodland edges, brushy thickets, prairies, fields, pastures, and orchards. Before European settlement, brown-headed cowbirds followed bison herds across the prairies.', 'Seeds and arthropods.', 'Summers in Montana from mid-May through late fall.', NULL, 'cowbird-text-map.png'),
  (66, 'Xanthocephalus xanthocephalus', 'Songbirds, Blackbirds', NULL, 'Male is 10.5″ in length. The head, neck, and breast are bright-yellow, while the body and eye areas are black. Its prominent white wing-patches are visible in flight. The female has almost half the body mass of the male. Its body is dull-brown; with pale-yellow on the neck, breast, throat, and eyebrow stripe. Both sexes have a harsh, grating song known as the ‘buzz song.’', 'Prairie wetlands and forested lakes.', 'Grain and weed seeds, and aquatic insects like dragonflies and damselflies.', 'Summers in Montana from late April through late September.', NULL, 'yellow_headed_blackbird-text-map.png'),
  (67, 'Agelaius phoeniceus', 'Songbirds, Blackbirds', NULL, 'The male is all black with a red shoulder and yellow wing bar. The female’s upper parts are brown; the underparts and wings are covered by a white and dark barring. Males are 8–9″ in length while the females are slightly smaller.', 'Wetland habitats like marshes, and upland habitats including alfalfa fields and other crop lands.', 'Seeds and arthropods.', 'Summers in Montana from mid-May through late fall.', NULL, 'redwinged_blackbird-text-map.png'),
  (68, 'Hirundo rustica', 'Songbirds, Swallows', NULL, 'A medium-sized swallow with a long, forked tail; steely-blue upperparts; reddish-brown underparts; and a chestnut-colored forehead.', 'Found in various habitats, including agricultural areas, cities, and suburbs. Originally nested in caves, it now breeds under the eaves of buildings or inside artificial structures such as bridges.', 'Predominately flying insects.', 'Summers in Montana from May to late August or mid-September.', NULL, 'barn_swallow-text-map.png'),
  (69, 'Riparia riparia', 'Songbirds, Swallows', NULL, 'A small swallow with a grayish-brown body and wings. Its throat and breast are white with a brown breast band.', 'Ocean coasts, rivers, streams, lakes, reservoirs, and wetlands. Nest colonies can range from 10 to close to 2000 active nests.', 'Predominately flying insects, but also terrestrial or aquatic insects.', 'Summers in Montana from May to late August or mid-September.', NULL, 'bank_swallow-text-map.png'),
  (70, 'Petrochelidon pyrrhonota', 'Songbirds, Swallows', NULL, 'A small bird, 5″ in length with a wingspan of 13″. The adult has dark-brownish plumage covering both their back and wings; a white forehead; reddish-orange cheeks; white underparts; pointed wings; and a short, square tail.', 'Canyons, foothills, escarpments, and river valleys that offered a vertical cliff face, also artificial nesting structures such as bridges and buildings close to fields or ponds that have a population of flying insects.', 'Predominately flying insects.', 'Summers in Montana from May through mid-September.', NULL, 'cliff_swallow-text-map.png'),
  (71, 'Toxostoma rufum', 'Songbirds, Thrashers', NULL, 'Up to 12″ in length. Adults have reddish-brown upperparts and whitish underparts streaked with splashes of black; a very long tail and 2 white wing-bars; a straight bill; and yellowish eyes. Males and females are alike in size and coloration.', 'Thickets and hedgerows in deciduous forest clearings in the Eastern U.S. In the Great Plains states it commonly breeds in fence-rows and windbreaks.', 'A ground foraging bird that feeds predominately on insects and other arthropods. By late summer it relies more on fruit and berries.', NULL, NULL, 'brown_thrasher-text-map.png'),
  (72, 'Mimus polyglottos', 'Songbirds, Thrashers', NULL, 'A medium-sized songbird 8–11″ in length with a tail almost as long as its body. The wingspan ranges from 12 to 15″. Its upper parts are gray, underparts are a white or whitish-gray color; and its wings have a black, posterior border. Renowned for its complex, mimicking song and for its pugnacious defense of its territory, nest, and young. Males and females are alike in size and coloration.', 'Open areas with sparse vegetation; desert scrub and chaparral are among its preferred habitats. Avoids deeply forested areas.', 'Feeds predominately on insects and other arthropods. By late summer it relies more on fruit, seeds, and berries. Occasionally small crustaceans and lizards.', NULL, NULL, 'mockingbird-text-map.png'),
  (73, 'Dumetella carolinensis', 'Songbirds, Thrashers', NULL, '8.5″ in length, the Catbird has a dark-gray body with a black cap; a long black tail; and reddish-brown plumage under its tail. Known for its cat-like call, it can also mimic the songs of other birds, as well as tree frogs. Males and females are alike in size and coloration.', 'Dense, thorny vegetation found in scrublands, woodland edges, overgrown farmland, and abandoned orchards.', 'Fruit, berries, and insects and invertebrates such as mealworms, earthworms, beetles, grasshoppers, caterpillars, and moths.', 'Summers from late May through mid-September.', NULL, 'catbird-text-map.png'),
  (74, 'Sialia currucoides', 'Songbirds, Thrushes', NULL, 'The Mountain Bluebird is 7″ in length. The adult male is bright turquoise-blue above and somewhat lighter-blue underneath, but with a white lower belly. An adult female’s wings and tail are a duller shade of blue, and the breast and crown are gray. Distinguished from the Eastern Bluebird by being more slender and completely blue (no orange).', 'Mountain environments or landscapes of sagebrush, where trees and shrubs are fairly spread out.', 'Arthropods such as grasshoppers and cicadas. Mostly berries in the winter months.', 'Summers in Montana from mid-March to mid-April through mid-September to mid-October.', NULL, 'mountain_bluebird-text-map.png'),
  (75, 'Sialia sialis', 'Songbirds, Thrushes', NULL, 'A small, stocky bird up to 8.5″ in length with a wingspan of 12″. The male has a bright-blue back, head, wings, and tail. The throat, sides of the neck, and upper breast are orange; with the orange on the breast extending down the flanks. The belly is bright white. The female is similarly colored, but duller overall. The Eastern Bluebird is distinguished by its orange throat, whereas the Mountain Bluebird’s throat is blue.', 'Found in habitats such as pastures, roadsides, farmlands, meadows, and yards that provide adequate foraging habitat', 'Mainly insects, but will also consume other invertebrates and small fruits.', 'Summers in Montana May through August.', NULL, 'eastern_bluebird-text-map.png'),
  (76, 'Turdus migratorius', 'Songbirds, Thrushes', NULL, 'A medium bird 10″ in length with a stocky build; the American Robin has dark gray upperparts; a blackish head; and white crescents above and below the eye. The breast and body are reddish-brown, and the throat is streaked black and white. Little difference between males and females.', 'One of the most widespread birds of North America, it breeds primarily in short-grass areas where trees and shrubs are present, such as residential areas, towns, farmyards, and parks.', 'Invertebrates (earthworms, beetle grubs, caterpillars, and grasshopper), fruits, and berries.', NULL, NULL, 'robin-text-map.png'),
  (77, 'Pelecanus erythrorhynchos', 'Waterbirds', NULL, 'The American White Pelican is a large, white bird up to 65″ in length, weighing up to 20 lbs., with a wingspan of up to 8′. Pelicans have webbed feet, and an enormous bill and pouch for catching and storing food.', 'Rivers, lakes, reservoirs, estuaries, bays, and marshes.', 'Predominately non-game fish such as carp and suckers, but also salamanders.', 'Pelicans migrate to Montana from either Southern California and Western Mexico or from the coastal areas of the Gulf of Mexico.', NULL, 'pelican-text-map.png'),
  (78, 'Antigone canadensis', 'Waterbirds', NULL, 'A tall, long-necked, long-legged bird that flies with its neck and legs fully extended. Adults are gray overall with red foreheads; white cheeks; and long, dark, pointed bills. Up to 54″ in height with a wingspan of 78″. No visual differences between sexes.', 'Found in open grasslands and marshes and along small valley streams.', 'Omnivorous. Grains, berries, invertebrates, some small mammals and reptiles.', 'Some are year-round residents; others migrate Northward through Montana in mid-April through mid-May and back south from late September through October.', 'They are seen as a smart bird for a number of reasons, but particularly because they were able to tell <i>Bitáalasshiaalitchiasshiituua</i> (Thrown Behind The Tipi Lining) where <i>Baaáalichkash</i> (Long Arm) was holding his brother, <i>Bahée Awúuasshiituuash</i> (Thrown Into The Spring).', 'sandhill_crane-text-map.png'),
  (79, 'Grus americana', 'Waterbirds', NULL, 'The tallest bird in North America, nearly 5′ in height.  White overall with black wingtips that are only visible in flight. Bare, red skin on the crown, cheek, and nape of the neck. No visual differences between sexes.', 'Northward migration through Eastern Montana in mid-April through mid-May and back south from late September through October.', 'Omnivorous. Grains, berries, invertebrates, some small mammals and reptiles.', 'Found in wet meadows and prairies, freshwater marshes and along small valley streams.', NULL, 'whooping_crane-text-map.png'),
  (80, 'Aythya americana', 'Waterbirds', NULL, 'A medium sized diving duck 16 to 22″ in length with a wingspan of up to 24″. Males have a reddish-brown head and neck, and a black breast. The body is grayish-white, and the rump and tail are black. The male’s bill are pale-blue with a black tip. Females have a yellowish-brown head and neck; their belly is white; and the rest of their body is brown. Its legs are set further back and its feet have a wider webbing than most ducks, making it specially adapted to foraging underwater.  The word <i>bíaxaake</i> can be used to describe ducks in general.', 'Lakes, ponds, and wetlands', 'Vegetative parts and tubers of submerged aquatic plants and aquatic invertebrates.', NULL, NULL, 'redhead_duck-text-map.png'),
  (81, 'Anas platyrhynchos', 'Waterbirds', NULL, 'A medium-sized dabbling duck. Males have a dark-green head and narrow white neck-ring; a chestnut-brown breast and neck; grayish underparts with a black rump and under tail-coverts; and white outer tail-feathers blue tinged with blue. Females are a mix of tan, white, gray, brown, or black feathers with white outer tail-feathers. Both sexes have a white and iridescent-blue patch bordering their wings. The word <i>bíaxaake</i> can be used to describe ducks in general.', 'The most abundant duck species in North America, it nests in wide variety of places including grasslands, marshes, bogs, roadside ditches, pastures, and cropland.', 'Omnivorous. Very flexible in food choices.', NULL, 'Mallards are the ones most commonly identified as the duck who brought the mud to <i>Iichíhkbaalia</i> to create the world. Mallard heads are placed on the stem of sacred pipes to commemorate the one that brought the mud that would lead to the creation of the <i>Apsáalooke</i> people.', 'mallard_duck-text-map.png'),
  (82, 'Mergus merganser', 'Waterbirds', NULL, 'A larger diving duck, 23–28″ in length with a wingspan of 30–38″. The male’s head is black with an iridescent-green sheen; white neck and underparts; black upper wings; gray back and tail; and a long, narrow scarlet-orange bill. The female has a rusty-brown head with a long crest and white chin patch; gray breast, back, wings and tail; white flanks and belly; and scarlet-orange bill. They are known for how they care for their young by carrying them on their backs.', 'They nest in tree cavities so require large lakes and rivers adjacent to mature forests for breeding. Capable of swimming deep in the water like Cormorants.', 'Primarily small fish, but also insects, mollusks, crustaceans, worms, frogs, small mammals, birds, and plants.', NULL, NULL, 'merganser-text-map.png'),
  (83, 'Fulica americana', 'Waterbirds', NULL, 'A stocky bodied bird, 17″ in length with a wingspan of 28″. Its head and neck are blackish and its body is slate-gray. The bill is short, thick, and white, with a white frontal shield that has a reddish-brown spot near the top between the eyes. No difference between sexes other than the female being slightly smaller. The word <i>bíaxaake</i> can be used to describe ducks in general.', 'Wetlands including freshwater lakes, ponds, marshes, and roadside ditches.', 'Aquatic plants but also grains and grasses.', 'Summers in Eastern Montana from April to June through late November. Year-round in Western Montana.', NULL, 'american_coot-text-map.png'),
  (84, 'Aix sponsa', 'Waterbirds', NULL, 'A medium sized dabbling duck, 21″ in length with a wingspan of 27″. The male has a distinctive facial pattern (an iridescent-green and purple head;a white throat with extensions onto the cheek and neck; red eyes; a long green, purple, and white crest; and a burgundy breast spotted with white). The female is brownish-gray with a pronounced white ring around the eye. Both sexes have the iridescent blue patch on the wing. The word <i>bíaxaake</i> can be used to describe ducks in general.', 'A variety of wetlands: creeks, rivers, swamps, marshes, and farm ponds.', 'Seeds, fruits and aquatic and terrestrial invertebrates.', NULL, NULL, 'wood_duck-text-map.png'),
  (85, 'Cygnus buccinator', 'Waterbirds', NULL, 'The largest waterfowl in North America, they can be up to 5′ in length, with a wingspan up to 80″, and weigh over 20 pounds. The body is entirely white. The webbed feet and legs are black. The bill is straight and is also black. Trumpeter swans are similar in size and weight to mute swans. However, the bill of mute swans is mostly orange rather than all black.', 'Lakes and ponds and adjacent marshes.', 'Almost entirely aquatic plants but occasionally invertebrates and fish.', 'Non-migrants spend both the breeding season and the winter primarily in the Red Rock Lakes National Wildlife Refuge. Those that breed in Northern Canada spend winters in Montana from mid-November through mid-April.', NULL, 'trumpeter_swan-text-map.png'),
  (86, 'Branta canadensis', 'Waterbirds', NULL, '25–46″ in length with a black head and a neck marked with a broad white chin strap extending from ear to ear; plain large dark wings; and a black tail with a U-shaped white band on the rump.', 'Island grasslands and meadows along rivers.', 'Vegetation from winter wheat fields in early fall, corn fields in mid-fall.', 'Canada geese have established breeding colonies in urban habitats, which provide food and few natural predators. They live year-round in the southern part of their breeding range including Montana. Northward migration from South Central Montana for breeding can happen any time from late February to late December.', NULL, 'goose-text-map.png'),
  (87, 'Anhinga anhinga', 'Waterbirds', NULL, 'A large bird 35″ in length and wingspan of nearly 4′. The yellow, sharply-pointed bill is twice the length of the head. The webbed feet are yellow as well. The male is black-green with the tip of its tail white. The female has a light-brown head, neck, and upper chest. Anhingas can swim underwater where they spear their prey with their beaks by thrusting out their elongated bent necks. Their feathers are not waterproof so they must bask in the sun with their wings spread in a semicircle to dry. The resemblance of this behavior to the male turkey has given them the nickname of ‘water turkey.’', 'They are native to the Gulf of Mexico’s coastal states.', 'Fish, amphibians, invertebrates and insects.', NULL, 'The <i>binnakáake</i> is the sacred bird of the Native American Church.', NULL),
  (88, 'Ardea herodias', 'Waterbirds', NULL, 'The largest heron in North America, 24″ tall and 48″ long with a wingspan of up to 80″. Named for its grayish-blue flight feathers. Upperparts are gray; its fore-neck is streaked with white, black, and rust-brown. It folds its neck in an ‘S’ shape and extends its legs along the body plane while in flight. Wing beats are slow.', 'Nesting colonies among cottonwoods on major rivers and lakes, or on islands in prairie wetlands.', 'Mostly fish but also amphibians, invertebrates, reptiles, mammals, and small birds.', 'Permanent resident in Western Montana. Summers in Eastern Montana, May through October.', NULL, 'great_blue_heron-text-map.png'),
  (89, 'Melanerpes erythrocephalus', 'Woodpeckers', NULL, 'Red-headed Woodpeckers average approximately 9″ in length. The entire head, neck and throat of both sexes is a bright red. The underparts are white and the back is a bluish-black. The word <i>akbannakkoopé</i> can be used to describe woodpeckers in general. No visual difference between males and females.', 'They are found in forest areas along major rivers.', 'Red-headed Woodpeckers eat insects and other invertebrates, berries and nuts, sap, and the young and eggs of birds.', 'Red-headed Woodpeckers arrive in Montana in mid-May and leave in mid-September.', NULL, 'woodpecker-text-map.png'),
  (90, 'Dryobates pubescens', 'Woodpeckers', NULL, 'The smallest woodpecker in North America, 5 to 7″ in length. Wings are mainly black with a white spotting; breast and belly are white; bill is small. Males have a red patch across the back of the head. Similar in appearance to the Hairy Woodpecker but much smaller. The word <i>akbannakkoopé</i> can be used to describe woodpeckers in general.', 'Found in deciduous forest areas, but also common at feeders in well shaded residential areas.', 'Foraging on trees for insects, nuts, and berries.', NULL, NULL, 'downy_woodpecker-text-map.png'),
  (91, 'Dryobates villosus', 'Woodpeckers', NULL, 'A medium-sized woodpecker, over 9″ in length, with white-spotted black wings, a relatively large bill, white underparts, and a black head with 2 large white bars on each side. Males have a red patch across the back of the head. Similar in appearance to the Downy Woodpecker but much larger. The word <i>akbannakkoopé</i> can be used to describe woodpeckers in general.', 'Primarily found in Douglas fir and Ponderosa pine forests, but can also be found in residential areas with mature shade trees.', 'Arthropod, fruits, and nuts.', NULL, NULL, 'hairy_woodpecker-text-map.png'),
  (92, 'Colaptes auratus cafer', 'Woodpeckers', NULL, 'The Northern Flicker is up to 14″ in length with a 22″ wingspan. Adults are brown with black bars on the back and wings. A necklace-like black patch occupies the upper breast, while the lower breast and belly are beige with black spots. The undertail and underwings are red and the primary wings have red shafts. It has a beige cap and a gray face. Males have a red moustache.', 'Open habitats near trees, including woodlands, yards, and parks.', 'Primarily food is insects, but they also eat seeds and berries. The Northern Flicker is the only member of the woodpecker family that feeds off the ground.', NULL, 'Flicker is a sacred bird and is associated with fire. This is why their feathers look like burning wood.', 'northen_flicker-text-map.png'),
  (93, 'Gallus gallus domesticus', 'Other', NULL, 'Originally native to Southeast Asia, chickens were domesticated 8,000 years ago and have become one of the world’s most common and widespread domesticated animals. Chickens live in flocks, incubate their eggs, and raise their young communally. The rooster’s crowing is loud and shrill. It can be a territorial warning to other males or a response to disturbances from outside their surroundings. Both hens and roosters have a crest on their heads called a comb or cockscomb, and hanging flaps of skin under their beaks called wattles; although these are more prominent in males.', NULL, 'Chickens are omnivores. In the wild they mainly feed on seeds and insects.', NULL, NULL, NULL),
  (94, 'Gallus gallus domesticus', 'Other', NULL, 'Originally native to Southeast Asia, chickens were domesticated 8,000 years ago and have become one of the world’s most common and widespread domesticated animals. Chickens live in flocks, incubate their eggs, and raise their young communally. The rooster’s crowing is loud and shrill. It can be a territorial warning to other males or a response to disturbances from outside their surroundings. Both hens and roosters have a crest on their heads called a comb or cockscomb, and hanging flaps of skin under their beaks called wattles; although these are more prominent in males.', NULL, 'Chickens are omnivores. In the wild they mainly feed on seeds and insects.', NULL, NULL, NULL),
  (95, 'Pavo cristatus', 'Other', NULL, 'The male (peacock) has a blue-colored head with a fan-shaped crest and is best known for his long train which is raised into a fan and displayed during courtship. The female (peahen) is predominantly brown in color, with a white face and iridescent-green lower neck. The peahen lacks the elaborate train of the male. Originally native to the Indian subcontinent, since the Middle Ages it has been introduced as an exotic species to other parts of the world through menageries and zoos. In some areas it has become feral.', NULL, 'Omnivorous. Grass, seeds, flower buds, fruits, insects, and small reptiles including snakes.', NULL, NULL, NULL),
  (96, 'Dromaius novaehollandiae', 'Other', NULL, 'Next to the ostrich, the Emu is the second largest bird in the world. Up to 75″ in height and 65″ in length weighing an average of between 69 and 82 lbs. Its neck is pale blue; plumage is gray-brown. Solar radiation is absorbed by the black tips of the feathers, the inner feathers then insulate the skin from the heat allowing them to be active during the day without overheating. Emus are flightless, but can run up to speeds of 30 miles per hour.', 'Various habitats across Australia both inland and near the coasts.', 'Native grasses and insects such as grasshoppers and crickets, beetles, cockroaches, ants, and spiders.', NULL, NULL, NULL),
  (97, 'Struthio camelus', 'Other', NULL, 'Ostriches are the world’s tallest and heaviest birds. They can be up to 9′ tall and weigh up to 290 lbs. Their long neck and legs keep their head way above ground and they have the largest eyes of any land vertebrate. Both of these features allow them to see predators from a long distance. The Ostrich can run for long distances at a speed of up to 34 miles per hour and can have short bursts of up to 60 miles per hour. Ostriches are the most dangerous birds on the planet for humans, with an average of two to three deaths being recorded each year in South Africa.', 'Open lands of the savannas of Sahara and sub-Saharan Africa.', 'Seeds, shrubs, grass, fruit, and flowers, occasionally insects and small reptiles such as lizards.', NULL, NULL, NULL),
  (98, 'Ara militaris', 'Other', NULL, 'A large bird, up to 33″ in length with a wingspan of 43″. Its plumage is green with light-blue tinges; flight and tail feathers are yellow; and its forehead has a bright-red patch. The bill is very large with a slate-gray, blackish tone. Noisy birds known for their loud cracking and shrieking calls, they live in large flocks and can survive up to 50–60 years in the wild.', 'Tropical deciduous and semi-deciduous forests of central Mexico through Northern Bolivia and Argentina.', 'Seeds, fruit, and leaves.', NULL, NULL, NULL),
  (99, 'Ara macao', 'Other', NULL, 'A large bird, 33″ in length, half of which is its tail. Mostly scarlet, its upper wings are yellow and dark-blue, as are the ends of its tail feathers. It has bare skin around the eye; a large white bill; and a black lower mandible. Scarlet macaws make very loud, high, and sometimes low-pitched, throaty squawks, squeaks and screams designed to travel long distances. They can live up to 75–90 years, but a more average lifespan is 45–50 years.', 'Humid, evergreen forests of South-Central Mexico to Peru, Ecuador, Bolivia, and Brazil.', 'Fruits, nuts, seeds, flowers and nectar.', NULL, NULL, NULL);
