INSERT INTO plants (id, latin_name, category, description_local, description_en, habitat_en, uses_en, map_image) VALUES
  (1, 'Berberis repens', 'Berries & Edible Fruits', NULL, 'A short shrub, ½–8″ tall. Bark is gray-purple to gray. Spreads by underground runner stems with roots being as deep as 18′. Leaves are twice as long as wide, with a rough surface, and leaflets paired opposite on either side of their stem. Upper surfaces are dark green, while the undersides are a lighter green, and covered with short, fine hairs. The edges of the leaves have spiny tips. Fragrant, densely packed groups of yellow flowers bloom in early spring. The berry fruit is dark purple-black and resembles grapes in texture.', 'Dry forests and foothills. Associated with lodgepole forests of the Rocky Mountains.', 'Berries eaten fresh, made into “Indian pudding”* or added to pemmican and baked goods or frozen for later use. In addition, historically the berries were mashed and made into patties and dried for later use.
